const API_URL='https://dummyjson.com/users';const STORAGE_KEY='teamdesk-employee-changes-v1';const PAGE_SIZE=10;
const $=s=>document.querySelector(s);const elements={search:$('#searchInput'),add:$('#addBtn'),export:$('#exportBtn'),role:$('#roleFilter'),sort:$('#sortSelect'),reset:$('#resetBtn'),retry:$('#retryBtn'),clear:$('#clearFiltersBtn'),body:$('#usersBody'),grid:$('#gridView'),table:$('#tableView'),loading:$('#loadingState'),error:$('#errorState'),empty:$('#emptyState'),pagination:$('#pagination'),pageSummary:$('#pageSummary'),pageButtons:$('#pageButtons'),previous:$('#previousPage'),next:$('#nextPage'),summary:$('#resultSummary'),message:$('#message'),apiStatus:$('#apiStatus'),details:$('#detailsDialog'),detailsBody:$('#detailsBody'),form:$('#formDialog'),userForm:$('#userForm'),formTitle:$('#formTitle'),formError:$('#formError'),deleteDialog:$('#deleteDialog'),deleteText:$('#deleteText'),confirmDelete:$('#confirmDelete'),save:$('#saveButton'),theme:$('#themeButton'),tableButton:$('#tableViewBtn'),gridButton:$('#gridViewBtn'),stats:{total:$('#totalStat'),admin:$('#adminStat'),moderator:$('#moderatorStat'),changes:$('#changesStat')}};
let users=[],filteredUsers=[],currentPage=1,currentView=localStorage.getItem('teamdesk-view')||'table',pendingDeleteId=null,nextLocalId=10000;
const icons={eye:'<svg viewBox="0 0 24 24"><path d="M3 12s3.2-6 9-6 9 6 9 6-3.2 6-9 6-9-6-9-6Z"/><circle cx="12" cy="12" r="2.5"/></svg>',edit:'<svg viewBox="0 0 24 24"><path d="m14 5 5 5M4 20l4-1 11-11-4-4L4 15v5Z"/></svg>',delete:'<svg viewBox="0 0 24 24"><path d="M4 7h16m-10 4v6m4-6v6M9 7l1-3h4l1 3m3 0-1 14H7L6 7"/></svg>'};
function escapeHTML(value=''){return String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));}
function getChanges(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY))||{added:[],updated:{},deleted:[]};}catch{return{added:[],updated:{},deleted:[]};}}
function saveChanges(changes){localStorage.setItem(STORAGE_KEY,JSON.stringify(changes));}
function applyLocalChanges(apiUsers){const changes=getChanges();const deleted=new Set(changes.deleted);const updated=apiUsers.filter(u=>!deleted.has(u.id)).map(u=>({...u,...changes.updated[u.id]}));return[...changes.added,...updated];}
function showToast(text,type='success'){elements.message.textContent=text;elements.message.className=`toast ${type} show`;clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>elements.message.className='toast',3200);}
function setControls(enabled){[elements.search,elements.add,elements.export,elements.role,elements.sort,elements.reset].forEach(el=>el.disabled=!enabled);}
function fullName(user){return`${user.firstName||''} ${user.lastName||''}`.trim();}
function avatar(user,size=''){const name=fullName(user);return user.image?`<img class="avatar ${size}" src="${escapeHTML(user.image)}" alt="${escapeHTML(name)}" loading="lazy">`:`<span class="avatar avatar-fallback ${size}" aria-hidden="true">${escapeHTML((user.firstName||'?')[0])}</span>`;}
function roleBadge(role='user'){const safe=['admin','moderator','user'].includes(role)?role:'user';return`<span class="role-badge role-${safe}">${safe}</span>`;}
function value(input){return input===undefined||input===null||input===''?'—':input;}
async function loadUsers(){elements.loading.hidden=false;elements.error.hidden=true;elements.empty.hidden=true;elements.table.hidden=true;elements.grid.hidden=true;elements.pagination.hidden=true;setControls(false);elements.apiStatus.textContent='Connecting to API';$('.api-status').classList.remove('live');try{const response=await fetch(`${API_URL}?limit=0`);if(!response.ok)throw new Error(`HTTP ${response.status}`);const data=await response.json();users=applyLocalChanges(data.users);nextLocalId=Math.max(10000,...users.map(u=>Number(u.id)||0))+1;elements.apiStatus.textContent='API connected';$('.api-status').classList.add('live');setControls(true);applyFilters();}catch(error){console.error(error);elements.error.hidden=false;elements.summary.textContent='The data request failed.';elements.apiStatus.textContent='API unavailable';}finally{elements.loading.hidden=true;}}
function applyFilters(resetPage=true){if(resetPage)currentPage=1;const query=elements.search.value.trim().toLowerCase();const role=elements.role.value;filteredUsers=users.filter(user=>{const haystack=`${fullName(user)} ${user.email||''} ${user.phone||''}`.toLowerCase();return(!query||haystack.includes(query))&&(role==='all'||user.role===role);});const sort=elements.sort.value;filteredUsers.sort((a,b)=>sort==='name-desc'?fullName(b).localeCompare(fullName(a)):sort==='age-asc'?(a.age||0)-(b.age||0):sort==='age-desc'?(b.age||0)-(a.age||0):fullName(a).localeCompare(fullName(b)));render();}
function render(){updateStats();const totalPages=Math.max(1,Math.ceil(filteredUsers.length/PAGE_SIZE));currentPage=Math.min(currentPage,totalPages);const start=(currentPage-1)*PAGE_SIZE;const page=filteredUsers.slice(start,start+PAGE_SIZE);elements.summary.textContent=`Showing ${filteredUsers.length} of ${users.length} employees`;elements.empty.hidden=filteredUsers.length!==0;elements.table.hidden=currentView!=='table'||!page.length;elements.grid.hidden=currentView!=='grid'||!page.length;elements.pagination.hidden=filteredUsers.length<=PAGE_SIZE;if(!page.length){elements.body.innerHTML='';elements.grid.innerHTML='';return;}elements.body.innerHTML=page.map(tableRow).join('');elements.grid.innerHTML=page.map(userCard).join('');renderPagination(totalPages,start,page.length);}
function tableRow(user){return`<tr><td><div class="user-cell">${avatar(user)}<div><strong>${escapeHTML(fullName(user))}</strong><span>#${escapeHTML(user.id)}</span></div></div></td><td><div class="contact-cell"><span>${escapeHTML(value(user.email))}</span><span>${escapeHTML(value(user.phone))}</span></div></td><td>${escapeHTML(value(user.age))}</td><td>${escapeHTML(value(user.gender))}</td><td>${roleBadge(user.role)}</td><td><div class="row-actions">${actionButtons(user.id)}</div></td></tr>`;}
function userCard(user){return`<article class="user-card">${avatar(user)}<h3>${escapeHTML(fullName(user))}</h3><p>${escapeHTML(value(user.email))}</p><footer>${roleBadge(user.role)}<div class="row-actions">${actionButtons(user.id)}</div></footer></article>`;}
function actionButtons(id){return`<button type="button" data-action="details" data-id="${id}" aria-label="View user details">${icons.eye}</button><button type="button" data-action="edit" data-id="${id}" aria-label="Edit user">${icons.edit}</button><button type="button" data-action="delete" data-id="${id}" aria-label="Delete user">${icons.delete}</button>`;}
function updateStats(){const changes=getChanges();elements.stats.total.textContent=users.length;elements.stats.admin.textContent=users.filter(u=>u.role==='admin').length;elements.stats.moderator.textContent=users.filter(u=>u.role==='moderator').length;elements.stats.changes.textContent=changes.added.length+Object.keys(changes.updated).length+changes.deleted.length;updateReports();}
function updateReports(){const total=Math.max(users.length,1);const counts={admin:users.filter(u=>u.role==='admin').length,moderator:users.filter(u=>u.role==='moderator').length,user:users.filter(u=>u.role==='user').length};const changes=getChanges();const localChanges=changes.added.length+Object.keys(changes.updated).length+changes.deleted.length;const set=(role,count)=>{const percent=Math.round(count/total*100);const value=$(`#${role}ReportValue`),bar=$(`#${role}ReportBar`);if(value)value.textContent=`${percent}%`;if(bar)bar.style.width=`${percent}%`;};set('user',counts.user);set('moderator',counts.moderator);set('admin',counts.admin);if($('#roleTotal'))$('#roleTotal').textContent=`${users.length} employees`;if($('#visibleReport'))$('#visibleReport').textContent=filteredUsers.length||users.length;if($('#changesReport'))$('#changesReport').textContent=localChanges;if($('#healthScore'))$('#healthScore').textContent=Math.max(82,100-Math.min(localChanges,18));const ages=users.map(u=>Number(u.age)).filter(Boolean);const average=ages.length?Math.round(ages.reduce((sum,age)=>sum+age,0)/ages.length):0;const female=users.filter(u=>u.gender==='female').length;const male=users.filter(u=>u.gender==='male').length;const departments=new Set(users.map(u=>u.company?.department).filter(Boolean));if($('#averageAgeReport'))$('#averageAgeReport').textContent=average||'—';if($('#femaleReport'))$('#femaleReport').textContent=`${Math.round(female/total*100)}%`;if($('#maleReport'))$('#maleReport').textContent=`${Math.round(male/total*100)}%`;if($('#departmentReport'))$('#departmentReport').textContent=departments.size||'—';}
function renderPagination(totalPages,start,count){elements.pageSummary.textContent=`${start+1}–${start+count} of ${filteredUsers.length}`;elements.previous.disabled=currentPage===1;elements.next.disabled=currentPage===totalPages;let pages=[];for(let page=1;page<=totalPages;page++){if(page===1||page===totalPages||Math.abs(page-currentPage)<=1)pages.push(page);else if(pages.at(-1)!=='…')pages.push('…');}elements.pageButtons.innerHTML=pages.map(page=>page==='…'?'<span>…</span>':`<button type="button" class="page-button ${page===currentPage?'active':''}" data-page="${page}">${page}</button>`).join('');}
function setView(view){currentView=view;localStorage.setItem('teamdesk-view',view);elements.tableButton.classList.toggle('active',view==='table');elements.gridButton.classList.toggle('active',view==='grid');elements.tableButton.setAttribute('aria-pressed',view==='table');elements.gridButton.setAttribute('aria-pressed',view==='grid');render();}
function showDetails(id){const user=users.find(u=>u.id===id);if(!user)return;const address=[user.address?.address,user.address?.city].filter(Boolean).join(', ');elements.detailsBody.innerHTML=`<div class="details-hero">${avatar(user)}<h2>${escapeHTML(fullName(user))}</h2><p>${escapeHTML(value(user.email))}</p></div><div class="details-grid">${detail('Role',user.role)}${detail('Phone',user.phone)}${detail('Age',user.age)}${detail('Gender',user.gender)}${detail('Address',address)}${detail('University',user.university)}${detail('Company',user.company?.name)}${detail('Job title',user.company?.title)}</div>`;elements.details.showModal();}
function detail(label,text){return`<div class="detail-item"><small>${label}</small><span>${escapeHTML(value(text))}</span></div>`;}
function openForm(id=null){elements.userForm.reset();elements.formError.hidden=true;$('#userId').value=id??'';if(id===null){elements.formTitle.textContent='Add employee';}else{const user=users.find(u=>u.id===id);if(!user)return;elements.formTitle.textContent='Edit employee';$('#firstName').value=user.firstName||'';$('#lastName').value=user.lastName||'';$('#email').value=user.email||'';$('#phone').value=user.phone||'';$('#age').value=user.age||'';$('#gender').value=user.gender||'';$('#role').value=user.role||'';}elements.form.showModal();setTimeout(()=>$('#firstName').focus(),50);}
function formData(){return{firstName:$('#firstName').value.trim(),lastName:$('#lastName').value.trim(),email:$('#email').value.trim(),phone:$('#phone').value.trim(),age:Number($('#age').value),gender:$('#gender').value,role:$('#role').value};}
function validate(data){if(!data.firstName||!data.lastName||!data.email||!data.phone||!data.gender||!data.role||!$('#age').value)return'Complete every field before saving.';if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email))return'Enter a valid email address.';if(data.age<1||data.age>120)return'Age must be between 1 and 120.';return'';}
async function saveUser(event){event.preventDefault();const data=formData();const error=validate(data);if(error){elements.formError.textContent=error;elements.formError.hidden=false;return;}elements.formError.hidden=true;elements.save.disabled=true;elements.save.textContent='Saving…';const id=Number($('#userId').value);try{if(id){await updateUser(id,data);}else{await createUser(data);}elements.form.close();applyFilters();showToast(id?'Employee updated successfully.':'Employee added successfully.');}catch(error){console.error(error);elements.formError.textContent='The request failed. Please try again.';elements.formError.hidden=false;}finally{elements.save.disabled=false;elements.save.textContent='Save employee';}}
async function createUser(data){const response=await fetch(`${API_URL}/add`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!response.ok)throw new Error(`HTTP ${response.status}`);await response.json();const user={...data,id:nextLocalId++,image:'',address:{},company:{},isLocal:true};users.unshift(user);const changes=getChanges();changes.added.unshift(user);saveChanges(changes);}
async function updateUser(id,data){const user=users.find(u=>u.id===id);if(!user)return;if(!user.isLocal){const response=await fetch(`${API_URL}/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!response.ok)throw new Error(`HTTP ${response.status}`);}Object.assign(user,data);const changes=getChanges();const addedIndex=changes.added.findIndex(u=>u.id===id);if(addedIndex>=0)changes.added[addedIndex]={...changes.added[addedIndex],...data};else changes.updated[id]={...(changes.updated[id]||{}),...data};saveChanges(changes);}
function askDelete(id){const user=users.find(u=>u.id===id);if(!user)return;pendingDeleteId=id;elements.deleteText.textContent=`${fullName(user)} will be removed from this local workspace.`;elements.deleteDialog.showModal();}
async function deleteUser(){const id=pendingDeleteId;const user=users.find(u=>u.id===id);if(!user)return;elements.confirmDelete.disabled=true;elements.confirmDelete.textContent='Deleting…';try{if(!user.isLocal){const response=await fetch(`${API_URL}/${id}`,{method:'DELETE'});if(!response.ok)throw new Error(`HTTP ${response.status}`);}users=users.filter(u=>u.id!==id);const changes=getChanges();const addedIndex=changes.added.findIndex(u=>u.id===id);if(addedIndex>=0)changes.added.splice(addedIndex,1);else{changes.deleted.push(id);delete changes.updated[id];}saveChanges(changes);elements.deleteDialog.close();applyFilters();showToast('Employee deleted from the workspace.');}catch(error){console.error(error);showToast('Could not delete this employee.','error');}finally{elements.confirmDelete.disabled=false;elements.confirmDelete.textContent='Delete employee';pendingDeleteId=null;}}
function handleAction(event){const button=event.target.closest('[data-action]');if(!button)return;const id=Number(button.dataset.id);if(button.dataset.action==='details')showDetails(id);if(button.dataset.action==='edit')openForm(id);if(button.dataset.action==='delete')askDelete(id);}
function resetFilters(){elements.search.value='';elements.role.value='all';elements.sort.value='name-asc';applyFilters();}
elements.search.addEventListener('input',()=>applyFilters());elements.role.addEventListener('change',()=>applyFilters());elements.sort.addEventListener('change',()=>applyFilters());elements.reset.addEventListener('click',resetFilters);elements.clear.addEventListener('click',resetFilters);elements.retry.addEventListener('click',loadUsers);elements.add.addEventListener('click',()=>openForm());elements.userForm.addEventListener('submit',saveUser);elements.body.addEventListener('click',handleAction);elements.grid.addEventListener('click',handleAction);elements.confirmDelete.addEventListener('click',deleteUser);elements.tableButton.addEventListener('click',()=>setView('table'));elements.gridButton.addEventListener('click',()=>setView('grid'));elements.previous.addEventListener('click',()=>{if(currentPage>1){currentPage--;render();}});elements.next.addEventListener('click',()=>{if(currentPage<Math.ceil(filteredUsers.length/PAGE_SIZE)){currentPage++;render();}});elements.pageButtons.addEventListener('click',event=>{const button=event.target.closest('[data-page]');if(button){currentPage=Number(button.dataset.page);render();}});document.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>document.getElementById(button.dataset.close).close()));document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close();}));document.addEventListener('keydown',event=>{if(event.key==='/'&&document.activeElement.tagName!=='INPUT'){event.preventDefault();elements.search.focus();}});
function exportEmployees(){if(!filteredUsers.length){showToast('No employee records to export.','error');return;}const columns=['Name','Email','Phone','Age','Gender','Role'];const rows=filteredUsers.map(user=>[fullName(user),user.email||'',user.phone||'',user.age||'',user.gender||'',user.role||'']);const csv=[columns,...rows].map(row=>row.map(value=>`"${String(value).replaceAll('"','""')}"`).join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`teamdesk-employees-${new Date().toISOString().slice(0,10)}.csv`;link.click();URL.revokeObjectURL(url);showToast(`${filteredUsers.length} employee records exported.`);}
elements.export.addEventListener('click',exportEmployees);document.querySelectorAll('[data-coming-soon]').forEach(button=>button.addEventListener('click',()=>showToast(`${button.dataset.comingSoon} analytics are planned for the next release.`)));
elements.theme.addEventListener('click',()=>{document.body.classList.toggle('light');localStorage.setItem('teamdesk-theme',document.body.classList.contains('light')?'light':'dark');});if(localStorage.getItem('teamdesk-theme')==='light')document.body.classList.add('light');setView(currentView);loadUsers();
